    colors = set(v for row in grid for v in row)
    best = None

    for base in colors:
        rs = [r for r in range(h) if base not in grid[r]]
        cs = [c for c in range(w) if all(grid[r][c] != base for r in range(h))]
        if len(rs) < 2 or len(cs) < 2:
            continue

        regions = [
            (r1, r2, c1, c2)
            for r1, r2 in zip(rs, rs[1:])
            for c1, c2 in zip(cs, cs[1:])
            if r2 - r1 > 1 and c2 - c1 > 1
        ]
        if not regions:
            continue
        density = sum(
            sum(grid[r][c] == base for r in range(r1 + 1, r2)
                for c in range(c1 + 1, c2))
            / ((r2 - r1 - 1) * (c2 - c1 - 1))
            for r1, r2, c1, c2 in regions
        ) / len(regions)
        score = density + 0.001 * len(regions)
        if best is None or score > best[0]:
            best = (score, base, rs, cs)

    _, base, rs, cs = best

    # Keep lattice lines that contain at least one colored marker.
    marker_colors = set(v for row in grid for v in row if v != base)
    rs = [r for r in rs if any(grid[r][c] in marker_colors for c in range(w))]
    cs = [c for c in cs if any(grid[r][c] in marker_colors for r in range(h))]

    nonbase = Counter(v for row in grid for v in row if v != base)
    separator = nonbase.most_common(1)[0][0]

    out = [[base for _ in range(len(cs) - 1)] for _ in range(len(rs) - 1)]
    for i in range(len(rs) - 1):
        for j in range(len(cs) - 1):
