def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    base = counts.most_common(1)[0][0]

    row_lines = [r for r in range(h) if base not in grid[r]]
    col_lines = [
        c for c in range(w)
        if all(grid[r][c] != base for r in range(h))
    ]

    # An all-separator column on the outer edge is only a frame, not a grid line.
    if col_lines and col_lines[0] == 0:
        col_lines = col_lines[1:]
    if col_lines and col_lines[-1] == w - 1:
        col_lines = col_lines[:-1]

    if len(row_lines) < 2 or len(col_lines) < 2:
        return []

    out = [[base for _ in range(len(col_lines) - 1)]
           for _ in range(len(row_lines) - 1)]

    # Paired markers along horizontal grid lines mark the cell below the segment.
    for i, r in enumerate(row_lines[:-1]):
        for j in range(len(col_lines) - 1):
            a, b = grid[r][col_lines[j]], grid[r][col_lines[j + 1]]
            if a == b and a != base:
                out[i][j] = a

    # Paired markers along vertical grid lines mark the cell to the right.
    for j, c in enumerate(col_lines[:-1]):
        for i in range(len(row_lines) - 1):
            a, b = grid[row_lines[i]][c], grid[row_lines[i + 1]][c]
            if a == b and a != base:
                out[i][j] = a

    return out
