from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    row_lines = []
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if count / w >= 0.80:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        color, count = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if count / h >= 0.80:
            col_lines.append(c)

    # An edge-only rail is the outer frame, not a boundary of an output cell.
    if col_lines and col_lines[0] == 0:
        col_lines = col_lines[1:]

    if len(row_lines) < 2 or len(col_lines) < 2:
        return []

    cell_colors = []
    for r0, r1 in zip(row_lines, row_lines[1:]):
        for c0, c1 in zip(col_lines, col_lines[1:]):
            cell_colors.extend(
                grid[r][c]
                for r in range(r0 + 1, r1)
                for c in range(c0 + 1, c1)
            )
    fill = Counter(cell_colors).most_common(1)[0][0]

    # The separator color is the most common color found on the rails.
    rail_colors = []
    for r in row_lines:
        rail_colors.extend(grid[r])
    for c in col_lines:
        rail_colors.extend(grid[r][c] for r in range(h))
    separator = Counter(rail_colors).most_common(1)[0][0]

    out = [[fill for _ in range(len(col_lines) - 1)]
           for _ in range(len(row_lines) - 1)]

    # Matching markers on a horizontal rail color the cell immediately below.
    for i, r in enumerate(row_lines[:-1]):
        for j, (c0, c1) in enumerate(zip(col_lines, col_lines[1:])):
            a, b = grid[r][c0], grid[r][c1]
            if a == b and a not in (fill, separator):
                out[i][j] = a

    return out
